def max_repeat(text, n=300):
    # find the largest repeated chunk approx: check if text has exact duplicate 300-char windows
    seen = {}
    best = 0
    step = 50
    for i in range(0, len(text)-n, step):
        w = text[i:i+n]
        if w in seen:
            best += 1
        else:
